export function getCountryCities(code: string): City[] {
  const lower = code.toLowerCase();
  if (COUNTRY_CITIES[lower]) {
    return COUNTRY_CITIES[lower].map(c => ({ ...c, defense: c.defense * 2 }));
  }
  // Default fallback for other countries
  return [
    { id: `${lower}_capital`, countryCode: lower, name: 'Başkent', population: '1.0 Milyon', isCapital: true, defense: 10000, lat: 0, lng: 0, isFallback: true },
  ];
}
